package ds.seed5503;

import ds.Item;
import ds.Max;
import ds.MeuItem;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.junit.runner.RunWith;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;

/**
 * Marker interface used to categorize unit tests so they can be selected
 * during test execution.
 */
interface UnitTest {}

/**
 * Improved tests for Max class.
 *
 * Notes:
 * - These tests aim to be more descriptive than autogenerated tests.
 * - Each test includes Given-When-Then style comments and clear assertion messages.
 *
 * Requirements referenced (examples):
 * - RQ-DS-MAX-001: method should return null when asked to consider 0 elements
 * - RQ-DS-MAX-002: method should throw a runtime exception when n exceeds available initialized elements
 */
@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, useJEE = true)
@Category(UnitTest.class)
public class EvoAITest extends Max_ESTest_scaffolding {

    /**
     * Given an array with only a couple of initialized MeuItem entries and many nulls,
     * When max(...) is invoked with n much larger than the array length,
     * Then a NullPointerException is expected because the implementation will attempt to access
     * elements that are not present or are null while computing the maximum.
     *
     * Requirement: RQ-DS-MAX-002
     */
    @Test(timeout = 4000)
    public void test0() throws Throwable {
        // Given
        final Item[] itemArray0 = new Item[6];
        final MeuItem first = new MeuItem(-728);
        final MeuItem second = new MeuItem(-333);
        itemArray0[0] = first;
        itemArray0[1] = second;

        // When / Then: request with an excessively large n should cause a runtime exception.
        try {
            Max.max(itemArray0, 390);
            fail("Expected a RuntimeException (NullPointerException or IndexOutOfBounds) when n exceeds array bounds");
        } catch (RuntimeException e) {
            // Accept NullPointerException or IndexOutOfBoundsException as valid failure modes for this invalid call.
            // We assert the type to ensure an unexpected checked exception is not thrown.
            assertTrue("Expected NullPointerException or IndexOutOfBoundsException but got: " + e.getClass(),
                    (e instanceof NullPointerException) || (e instanceof IndexOutOfBoundsException));
        }
    }

    /**
     * Given an array where the first two positions reference identical MeuItem objects and remaining positions are null,
     * When max(...) is invoked with n that exceeds array bounds, the implementation should fail fast with a runtime exception.
     * Additionally, invoking max(..., 0) should be a valid call and return null (no elements considered).
     *
     * Requirement: RQ-DS-MAX-001, RQ-DS-MAX-002
     */
    @Test(timeout = 4000)
    public void test1() throws Throwable {
        // Given
        final Item[] itemArray0 = new Item[6];
        final MeuItem repeated = new MeuItem(-728);
        itemArray0[0] = repeated;
        itemArray0[1] = repeated;

        // When / Then: n == 0 should return null (no elements considered)
        Item resultForZero = Max.max(itemArray0, 0);
        assertNull("When n is 0, Max.max should return null since no elements are considered", resultForZero);

        // When / Then: n much larger than array length should cause a runtime exception.
        try {
            Max.max(itemArray0, 390);
            fail("Expected a RuntimeException (NullPointerException or IndexOutOfBounds) when n exceeds array bounds");
        } catch (RuntimeException e) {
            assertTrue("Expected NullPointerException or IndexOutOfBoundsException but got: " + e.getClass(),
                    (e instanceof NullPointerException) || (e instanceof IndexOutOfBoundsException));
        }
    }

    /**
     * Given an array of length 8 where all entries are null,
     * When max(..., 0) is invoked,
     * Then the result should be null (no elements considered).
     *
     * Requirement: RQ-DS-MAX-001
     */
    @Test(timeout = 4000)
    public void test2() throws Throwable {
        // Given
        final Item[] itemArray0 = new Item[8]; // all entries are null by default

        // When
        Item item0 = Max.max(itemArray0, 0);

        // Then
        assertNull("Expected null when asking for max among 0 elements even if the array has null entries", item0);
    }

    /**
     * Sanity and basic API contract checks for Max.
     *
     * Given a brand new Max instance,
     * When it is used to compute max over empty and small arrays,
     * Then behaviour should be consistent with documented expectations:
     * - empty consideration (n=0) -> null
     * - trivial single-item -> returns that item
     *
     * Requirement: RQ-DS-MAX-001, RQ-DS-MAX-003
     */
    @Test(timeout = 4000)
    public void test3() throws Throwable {
        // Given
        Max maxInstance = new Max();
        final Item[] emptyArray = new Item[0];

        // When / Then: empty consideration returns null
        Item r1 = Max.max(emptyArray, 0);
        assertNull("Max over zero elements should be null", r1);

        // Given a single-element array
        final Item[] oneElement = new Item[1];
        final MeuItem only = new MeuItem(42);
        oneElement[0] = only;

        // When: consider the single element
        Item r2 = Max.max(oneElement, 1);

        // Then: result should be the same instance we provided
        assertSame("Max over a single element should return that element instance", only, r2);
        assertEquals("Returned element should preserve its value when queried via toString or equals if implemented",
                only.toString(), r2.toString());
    }
}